    @Test void concurrentSensitiveLimitsAreAtomicAndFailuresDoNotLockEmployeePermanently()throws Exception{var gate=new CountDownLatch(1);try(var pool=Executors.newFixedThreadPool(16)){var results=new ArrayList<Future<Boolean>>();for(int i=0;i<24;i++)results.add(pool.submit(() -> {gate.await();try{sessions.limitSensitive("technical-source",initialized.tenantId(),initialized.employeeId(),target);return true;}catch(BusinessException e){assertEquals(ErrorCode.RATE_LIMITED,e.error().code());return false;}}));gate.countDown();int allowed=0;for(var r:results)if(r.get(10,TimeUnit.SECONDS))allowed++;assertEquals(8,allowed);}String t=token("admin");var r=change(t,password,next);error(r,429,"RATE_LIMITED");assertTrue(r.headers().firstValue("Retry-After").isPresent());stored(initialized.employeeId(),password,0,false);assertEquals(200,me(t).statusCode());}
