    @Test void partiallyDeletedTokenIndexStillCleansOrphanSessionAndTerminal()throws Exception{grantRevoke();String a=token("admin"),old=token("worker");CONTROL.cleanupFailures.set(1);assertEquals("PENDING",revoke(a,target,"0").headers().firstValue("X-Session-Cleanup").orElseThrow());redis.delete("pet:test:staff:staff:token:"+old);assertNotNull(redis.getSession("pet:test:staff:staff:token-session:"+old));sessions.revokeBefore(initialized.tenantId(),target,1);assertNull(redis.getSession("pet:test:staff:staff:token-session:"+old));assertNull(redis.getSession("pet:test:staff:staff:session:"+target));assertNull(redis.get("pet:test:staff:staff:last-active:"+old));}
    static class Gate {final CountDownLatch entered=new CountDownLatch(1),release=new CountDownLatch(1);void await(){entered.countDown();try{if(!release.await(12,TimeUnit.SECONDS))throw new IllegalStateException("测试屏障超时");}catch(InterruptedException e){Thread.currentThread().interrupt();throw new IllegalStateException("测试屏障中断");}}}
    static class Controls {
        volatile Runnable afterCommit,beforeFinal;final ThreadLocal<Boolean> wroteSuccess=new ThreadLocal<>();AtomicBoolean rollback=new AtomicBoolean();AtomicInteger cleanupFailures=new AtomicInteger();volatile CyclicBarrier parallel;volatile Gate login;ThreadLocal<Integer> loginLoads=new ThreadLocal<>();
        void clear(){afterCommit=null;beforeFinal=null;wroteSuccess.remove();rollback.set(false);cleanupFailures.set(0);parallel=null;if(login!=null)login.release.countDown();login=null;loginLoads.remove();}
        Object invoke(Object bean,Method method,Object[] args)throws Throwable {
            if(method.getName().equals("lockTenant") && parallel!=null)parallel.await(10,TimeUnit.SECONDS);
            if(method.getName().equals("revokeBefore") && cleanupFailures.getAndUpdate(n -> Math.max(0,n-1))>0)throw new BusinessException(ErrorCode.DEPENDENCY_UNAVAILABLE);
            if(method.getName().equals("create"))loginLoads.set(0);
            try {
                Object value;try{value=method.invoke(bean,args);}catch(InvocationTargetException e){throw e.getCause();}
                if(method.getName().equals("load") && login!=null && loginLoads.get()!=null){int count=loginLoads.get()+1;loginLoads.set(count);if(count==1)login.await();}
                if(method.getName().equals("event") && "SUCCESS".equals(args[3])){wroteSuccess.set(true);if(beforeFinal!=null){beforeFinal.run();beforeFinal=null;}}
                if(method.getName().equals("transaction") && Boolean.TRUE.equals(wroteSuccess.get())){wroteSuccess.remove();if(afterCommit!=null){afterCommit.run();afterCommit=null;}}
                if(method.getName().equals("revoke") && rollback.compareAndSet(true,false))throw new BusinessException(ErrorCode.DEPENDENCY_UNAVAILABLE);
                return value;
            } finally {if(method.getName().equals("create"))loginLoads.remove();if(method.getName().equals("transaction"))wroteSuccess.remove();}
        }
    }
    @TestConfiguration(proxyBeanMethods=false) static class Probes {
        @Bean static BeanPostProcessor faultPorts(){return new BeanPostProcessor(){@Override public Object postProcessAfterInitialization(Object bean,String name){Class<?> type=switch(name){case "staffSecurityJdbc" -> StaffSecurityStore.class;case "staffSessionPort" -> StaffSessionPort.class;case "authenticationJdbc" -> IdentityLookup.class;default -> null;};return type==null?bean:java.lang.reflect.Proxy.newProxyInstance(type.getClassLoader(),new Class[]{type},(proxy,method,args) -> CONTROL.invoke(bean,method,args));}};}
        @Bean QueueProbe queueProbe(TenantTaskExecutor tasks){return new QueueProbe(tasks);}
    }
    @RestController static class QueueProbe {
        final TenantTaskExecutor tasks;volatile Future<?> future;volatile DataScope scope;volatile String token;final AtomicBoolean ran=new AtomicBoolean();QueueProbe(TenantTaskExecutor tasks){this.tasks=tasks;}
        @GetMapping("/api/admin/__credential-test/queue") ApiResponse.Success<Void> queue(jakarta.servlet.http.HttpServletRequest request){token=StaffHttpAuthentication.current(request).token();try(var s=TenantExecutionScope.forPermission("identity:user:list")){future=tasks.submit(() -> {scope=TenantContextHolder.current().orElseThrow().dataScope();ran.set(true);return null;});return ApiResponse.success(null);}}
    }
